window.OdioNetwork=(()=>{
  const C=OdioNetworkCore,storageKey='eof-nodos-v1',thoughtKey='eof-pensamientos-v1';
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let host,nodes=[],selectedId='w1',view='explore',zoom=1,filter='Todos',pendingTopic='',draft='',positions=new Map(),inspectorHidden=false,pan=null;
  const localNodes=()=>{try{const raw=JSON.parse(localStorage.getItem(storageKey)||'[]');return Array.isArray(raw)?raw.slice(-60).filter(n=>n&&typeof n.text==='string'&&C.topics.includes(n.topic)&&typeof n.id==='string').map(n=>({...C.makeNode(n.text,n.topic,n.id),createdAt:n.createdAt})):[]}catch{return[]}};
  const savedThoughts=()=>{try{const data=JSON.parse(localStorage.getItem(thoughtKey)||"[]");return Array.isArray(data)?data.filter(t=>t&&typeof t.text==="string"&&Array.isArray(t.topics)&&Array.isArray(t.keywords)).slice(-30):[]}catch{return[]}};
  const selected=()=>nodes.find(n=>n.id===selectedId)||nodes[0];
  function markup(){return `<div id="nodal-app" class="nodal-app"></div>`}
  function init(){host=document.querySelector('#nodal-app');nodes=[...C.seeds,...localNodes()];selectedId=nodes.filter(n=>n.local).at(-1)?.id||'w1';view='explore';zoom=1;filter='Todos';inspectorHidden=false;pan=null;host.addEventListener('click',onClick);host.addEventListener('submit',onSubmit);host.addEventListener('input',onInput);host.addEventListener('change',onChange);render()}
  function destroy(){if(host){host.removeEventListener('click',onClick);host.removeEventListener('submit',onSubmit);host.removeEventListener('input',onInput);host.removeEventListener('change',onChange)}host=null}
  function render(){if(!host)return;host.classList.toggle("is-exploring",view==="explore");host.innerHTML=`<header class="nodal-heading"><div><p class="eyebrow">COMUNIDAD DEL ODIO / REGISTROS QUE SE CRUZAN</p><h2 id="modal-title">LO QUE TE PASA<br><em>HACE RED.</em></h2></div><div class="nodal-header-actions"><button class="pill" data-net="create">+ CREAR MI NODO</button><button class="nodal-small" data-net="saved">MIS PENSAMIENTOS (${savedThoughts().length})</button></div></header><div class="nodal-disclosure">PROTOTIPO LOCAL · ${C.seeds.length} REGISTROS DE EJEMPLO · ${nodes.filter(n=>n.local).length} NODOS TUYOS EN ESTE NAVEGADOR</div>${view==='create'?createView():view==='saved'?savedView():exploreView()}`;if(view==='explore'){drawGraph();centerGraph();enableDrag();}}
  function savedView(){const saved=savedThoughts().reverse();return `<div class="saved-thoughts"><p class="eyebrow" style="margin-top:35px">TUS PALABRAS QUEDAN ACÁ.</p>${saved.length?saved.map(r=>`<article class="saved-thought"><h3>${esc(r.text)}</h3><p>${r.topics.map(esc).join(" / ")} · ${r.keywords.map(esc).join(" / ")}</p></article>`).join(""):`<p class="thought-empty">Todavía no tenés pensamientos guardados en este navegador.</p>`}<button class="pill" data-net="explore" style="margin-top:30px">← VOLVER A LA RED</button></div>`}
  function createView(){return `<div class="nodal-create"><div class="nodal-intro"><p class="eyebrow">01 / PONER AFUERA</p><h3>DECILO COMO<br>TE SALGA.</h3><p>Tu registro tiene un lugar en la red. El tópico lo acerca a otras voces; las palabras compartidas abren conexiones con otros temas.</p><button class="nodal-small" data-net="explore">← VOLVER A LA RED</button></div><form id="node-form"><label for="node-text">¿QUÉ TE MOLESTA? ¿QUÉ VENÍS AGUANTANDO?</label><textarea id="node-text" minlength="8" maxlength="500" required placeholder="Me desgasta trabajar todo el día y sentir que no tengo tiempo para mí…">${esc(draft)}</textarea><div class="form-info"><span>Sin nombre. Guardado solo en este navegador.</span><span id="node-count">${draft.length} / 500</span></div><label for="node-topic">¿DE QUÉ HABLA TU NODO?</label><select id="node-topic" required><option value="">Elegí un tópico</option>${C.topics.map(t=>`<option ${pendingTopic===t?'selected':''}>${t}</option>`).join('')}</select><p id="topic-hint" class="nodal-muted">Podés elegir el tema que mejor represente lo que escribiste.</p><p id="node-keywords" class="nodal-keyword-preview">${keywordPreview(draft)}</p><button class="pill" type="submit">CONSTRUIR MI NODO <span>↗</span></button><p id="node-error" role="status"></p></form></div>`}
  function keywordPreview(text){const words=C.keywords(text);return words.length?'PALABRAS QUE APARECEN: '+words.map(w=>w.toUpperCase()).join(' / '):'Tus palabras en común van a aparecer acá mientras escribís.'}
  function exploreView(){const node=selected(),related=C.related(node,nodes),visible=nodes.filter(n=>filter==='Todos'||n.topic===filter);return `<div class="nodal-toolbar"><label>EXPLORAR POR TÓPICO <select id="network-filter"><option>Todos</option>${C.topics.map(t=>`<option ${filter===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="nodal-legend"><span><i></i> REGISTRO</span><span><i class="your-dot"></i> TU NODO</span><span>— CONEXIÓN POR TEMA O PALABRA</span></div></div><div class="nodal-workspace"><div class="graph-column"><div class="graph-controls"><span>ARRASTRÁ PARA RECORRER · RUEDA PARA ZOOM · TOCÁ UN NODO PARA LEERLO</span><div><button data-net="toggle-list">REGISTROS</button><button data-net="zoom-out" aria-label="Alejar red">−</button><button data-net="zoom-reset">RESTAURAR</button><button data-net="zoom-in" aria-label="Acercar red">+</button></div></div><div class="graph-scroll" tabindex="0" aria-label="Red nodal, desplazable horizontalmente"><div class="graph-scene" style="width:${Math.max(innerWidth*1.7,1800)*zoom}px;height:${Math.max(innerHeight*1.6,1170)*zoom}px"><svg id="graph-lines" viewBox="0 0 1000 650" preserveAspectRatio="none" aria-hidden="true"></svg><div id="graph-points"></div></div></div><details class="nodal-record-list"><summary>VER LOS ${visible.length} REGISTROS COMO LISTA</summary><div>${visible.map(n=>`<button data-node="${esc(n.id)}">${esc(n.topic)} / ${esc(n.text.slice(0,80))}${n.text.length>80?'…':''}</button>`).join('')}</div></details></div><aside class="node-inspector ${inspectorHidden?'is-hidden':''}"><button class="inspector-toggle" data-net="toggle-inspector" aria-label="Ocultar ficha del nodo">×</button><div class="inspector-top"><span>${node.local?'TU NODO / LOCAL':'REGISTRO DE EJEMPLO'}</span><span>${esc(node.topic.toUpperCase())}</span></div><h3>${esc(shortLabel(node))}</h3><blockquote>${esc(node.text)}</blockquote>${node.local?`<button class="nodal-small remove-node" data-net="remove-node">RETIRAR ESTE NODO LOCAL ×</button>`:""}<div class="node-tags">${node.keywords.map(w=>`<span>${esc(w)}</span>`).join('')||'<span>Conectado por tópico</span>'}</div><h4>${related.length} CONEXIONES CON SENTIDO</h4><div class="related-records">${related.slice(0,5).map(r=>`<button data-node="${esc(r.node.id)}"><span>${esc(r.node.topic)} ${r.node.local?'· TU NODO':''} ↗</span><strong>${esc(r.node.text.slice(0,92))}${r.node.text.length>92?'…':''}</strong><small>${esc(reason(r))}</small></button>`).join('')||'<p>Todavía no hay otro registro conectado. Las conexiones aparecen al compartir tema o palabras con otras voces.</p>'}</div></aside></div>`}
  function reason(r){return(r.sameTopic?'MISMO TÓPICO'+(r.words.length?' · ':''):'OTRO TÓPICO · ')+(r.words.length?'EN COMÚN: '+r.words.join(', '):'')}
  function shortLabel(n){if(n.local)return 'LO QUE VOS DESCARGASTE';const labels={w1:'EL TRABAJO ME CONSUME',w2:'RENDIR MÁS. COBRAR LO MISMO.',w3:'¿Y MI TIEMPO?',r1:'REPETIR HASTA EL DESGASTE',r2:'VIVIR EN AUTOMÁTICO',r3:'CALLAR TAMBIÉN CANSA',s1:'LA VIDA NO ALCANZA',s2:'COMPETIR O ENCONTRARNOS',a1:'LA PRESIÓN NO PARA',a2:'MIEDO EN SILENCIO',c1:'CUATRO HORAS MENOS',c2:'NO ME ESCUCHO',k1:'COMPRAR NO LO RESUELVE',k2:'SIEMPRE FALTA ALGO'};return labels[n.id]||n.topic}
  function drawGraph(){const hubs=[[290,210],[630,130],[780,400],[260,490],[100,340],[550,500]],visible=nodes.filter(n=>filter==='Todos'||n.topic===filter),svg=host.querySelector('#graph-lines'),points=host.querySelector('#graph-points');positions=new Map();for(let ti=0;ti<C.topics.length;ti++){const group=visible.filter(n=>n.topic===C.topics[ti]);const hub=hubs[ti];group.forEach((n,i)=>{const angle=(i*2.399+ti*.8),radius=70+Math.floor(i/5)*36;positions.set(n.id,{x:Math.max(28,Math.min(925,hub[0]+Math.cos(angle)*radius)),y:Math.max(60,Math.min(590,hub[1]+Math.sin(angle)*radius))})})}
    const relatedIds=new Set(C.related(selected(),nodes).map(r=>r.node.id));const edges=C.connections(visible);svg.innerHTML=edges.map(e=>{const a=positions.get(e.a),b=positions.get(e.b),focus=e.a===selectedId||e.b===selectedId;return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" class="${focus?'is-connected':''}"/>`}).join('');
    points.innerHTML=C.topics.filter(t=>visible.some(n=>n.topic===t)).map(t=>{const hub=hubs[C.topics.indexOf(t)];return `<span class="graph-topic" style="left:${hub[0]/10}%;top:${hub[1]/6.5}%">${esc(t.toUpperCase())}</span>`}).join('')+visible.map(n=>{const p=positions.get(n.id);return `<button class="graph-node ${n.id===selectedId?'is-selected':''} ${relatedIds.has(n.id)?'is-related':''} ${n.local?'is-yours':''}" data-node="${esc(n.id)}" style="left:${p.x/10}%;top:${p.y/6.5}%" aria-pressed="${n.id===selectedId}" aria-label="${esc(n.topic+': '+n.text)}"><i></i><span>${esc(n.local?'TU NODO':shortLabel(n))}</span></button>`}).join('');
  }
  function centerGraph(){const viewport=host.querySelector(".graph-scroll"),scene=host.querySelector(".graph-scene"),p=positions.get(selectedId);if(!viewport||!scene||!p)return;viewport.scrollLeft=Math.max(0,p.x/1000*scene.clientWidth-viewport.clientWidth*.42);viewport.scrollTop=Math.max(0,p.y/650*scene.clientHeight-viewport.clientHeight*.48);}
  function setGraphZoom(value,clientX,clientY){
    const viewport=host?.querySelector('.graph-scroll'),scene=host?.querySelector('.graph-scene');
    if(!viewport||!scene)return;
    const next=Math.max(.65,Math.min(1.8,value));
    if(next===zoom)return;
    const rect=viewport.getBoundingClientRect();
    const x=clientX===undefined?viewport.clientWidth/2:clientX-rect.left-viewport.clientLeft;
    const y=clientY===undefined?viewport.clientHeight/2:clientY-rect.top-viewport.clientTop;
    const anchorX=(viewport.scrollLeft+x)/scene.clientWidth;
    const anchorY=(viewport.scrollTop+y)/scene.clientHeight;
    zoom=next;
    scene.style.width=`${Math.max(innerWidth*1.7,1800)*zoom}px`;
    scene.style.height=`${Math.max(innerHeight*1.6,1170)*zoom}px`;
    viewport.scrollLeft=anchorX*scene.clientWidth-x;
    viewport.scrollTop=anchorY*scene.clientHeight-y;
    pan=null;
    viewport.classList.remove('is-dragging');
  }
  function onGraphWheel(e){
    if(!e.deltaY)return;
    e.preventDefault();
    const viewport=e.currentTarget;
    const unit=e.deltaMode===1?16:e.deltaMode===2?viewport.clientHeight:1;
    const delta=Math.max(-240,Math.min(240,e.deltaY*unit));
    setGraphZoom(zoom*Math.exp(-delta*.0015),e.clientX,e.clientY);
  }
  function enableDrag(){const viewport=host.querySelector(".graph-scroll");viewport.addEventListener('wheel',onGraphWheel,{passive:false});viewport.onpointerdown=e=>{if(e.button!==0||e.target.closest("button"))return;pan={x:e.clientX,y:e.clientY,left:viewport.scrollLeft,top:viewport.scrollTop};viewport.setPointerCapture(e.pointerId);viewport.classList.add("is-dragging");};viewport.onpointermove=e=>{if(!pan)return;viewport.scrollLeft=pan.left-(e.clientX-pan.x);viewport.scrollTop=pan.top-(e.clientY-pan.y);};const end=()=>{pan=null;viewport.classList.remove("is-dragging")};viewport.onpointerup=end;viewport.onpointercancel=end;viewport.onlostpointercapture=end;}
  function onClick(e){const target=e.target.closest('button');if(!target)return;if(target.dataset.node){selectedId=target.dataset.node;inspectorHidden=false;filter="Todos";view='explore';render();return}switch(target.dataset.net){case'toggle-list':{const list=host.querySelector('.nodal-record-list');list.open=!list.open;break;}case'toggle-inspector':inspectorHidden=!inspectorHidden;host.querySelector('.node-inspector')?.classList.toggle('is-hidden',inspectorHidden);break;case'remove-node':{const node=selected();if(!node.local)return;const rest=nodes.filter(n=>n.local&&n.id!==node.id);try{localStorage.setItem(storageKey,JSON.stringify(rest));nodes=[...C.seeds,...rest];selectedId='w1';render()}catch{target.textContent='NO SE PUDO RETIRAR. REVISÁ EL ALMACENAMIENTO.'}break;}case'saved':view='saved';render();break;case'create':view='create';draft='';pendingTopic='';render();host.querySelector('#node-text').focus();break;case'explore':view='explore';render();break;case'zoom-in':setGraphZoom(zoom+.2);break;case'zoom-out':setGraphZoom(zoom-.2);break;case'zoom-reset':zoom=1;render();break;}}
  function onInput(e){if(e.target.id==='node-text'){draft=e.target.value;host.querySelector('#node-count').textContent=draft.length+' / 500';host.querySelector('#node-keywords').textContent=keywordPreview(draft);const suggested=C.suggestTopic(draft);host.querySelector('#topic-hint').textContent=suggested?'POR TUS PALABRAS, PODRÍA SER: '+suggested.toUpperCase()+'. Podés cambiarlo.':'Elegí el tema que mejor represente lo que escribiste.';if(!pendingTopic&&suggested)host.querySelector('#node-topic').value=suggested}}
  function onChange(e){if(e.target.id==='node-topic')pendingTopic=e.target.value;if(e.target.id==='network-filter'){filter=e.target.value;const found=nodes.find(n=>filter==='Todos'||n.topic===filter);if(found&&filter!=='Todos')selectedId=found.id;render()}}
  function onSubmit(e){if(e.target.id!=='node-form')return;e.preventDefault();try{const node=C.makeNode(draft,host.querySelector('#node-topic').value,'local-'+(crypto.randomUUID?.()||Date.now()));const previous=nodes.filter(n=>n.local);localStorage.setItem(storageKey,JSON.stringify([...previous,node].slice(-60)));nodes=[...C.seeds,...[...previous,node].slice(-60)];selectedId=node.id;view='explore';filter='Todos';draft='';render();}catch(error){host.querySelector('#node-error').textContent=error.message||'No se pudo guardar el nodo. Revisá el almacenamiento del navegador.'}}
  return{markup,init,destroy};
})();
